'use client';

/**
 * Renders report-card HTML generated by Laravel exactly as the legacy ERP shows it.
 *
 * The server's HTML is only a fragment: its look comes from Laravel's `/css/result.css`
 * (orange headers, borders, background art, Saira font) and its logos / signatures are
 * root-relative paths like `/storage/result/left_logo/...` that only resolve on the
 * Laravel host. Dropping that HTML straight into this app loses both.
 *
 * So it is rendered in a sandboxed (no scripts) iframe that loads the Laravel stylesheet,
 * with every root-relative URL rewritten to the Laravel origin. A `<base>` tag is not
 * used because the app's CSP enforces `base-uri 'self'`.
 */

import React, { useEffect, useMemo, useRef } from 'react';
import { API_BASE_URL } from '@/app/components/utils/api_url';
import { sanitizeHtml } from '@/lib/security/sanitize-html';

/** `/storage/x.png` -> `https://erp.example/storage/x.png`; leaves `//cdn`, `http(s):`, `data:` alone. */
export function absolutizeRootRelativeUrls(html: string, origin: string): string {
  if (!origin) return html;
  return html
    .replace(/(\s(?:src|href|background|poster)\s*=\s*["'])\/(?!\/)/gi, `$1${origin}/`)
    .replace(/url\(\s*(["']?)\/(?!\/)/gi, `url($1${origin}/`);
}

/**
 * Print rules. Laravel emits one `<div id="{student}">` per report card as a direct child of
 * <body>. The legacy print window put a page break before each one (and its own inline
 * `page-break:always` is not a valid property, so it did nothing here). Grand-marksheet
 * templates are the exception: they deliberately fit several students on one page.
 */
function printRules(onePerPage: boolean): string {
  const keep = 'break-inside: avoid; page-break-inside: avoid;';
  return onePerPage
    ? `@media print {
  body > div[id] { ${keep} break-after: page; page-break-after: always; }
  body > div[id]:last-of-type { break-after: auto; page-break-after: auto; }
}`
    : `@media print { body > div[id] { ${keep} } }`;
}

export function buildLegacyReportDocument(html: string, origin = API_BASE_URL, onePerPage = true): string {
  const body = absolutizeRootRelativeUrls(sanitizeHtml(html), origin);
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<link rel="stylesheet" href="${origin}/css/result.css">
<style>
  /* result.css points at the Laravel host's /fonts, which the browser blocks cross-origin (no CORS header).
     Serve the same Saira file from this app instead; srcdoc resolves "/fonts/..." against the app origin. */
  @font-face {
    font-family: 'Saira Semi Condensed'; font-style: normal; font-weight: 400;
    src: url('/fonts/saira-semi-condensed-v4-latin-regular.woff2') format('woff2'),
         url('/fonts/saira-semi-condensed-v4-latin-regular.woff') format('woff');
  }
  html, body { margin: 0; padding: 0; background: #fff; color: #000; }
  body { padding: 8px; font-family: 'Saira Semi Condensed', Arial, sans-serif; }
  img { max-width: 100%; }
  /* Paper output follows the browser's own "Background graphics" setting, exactly like the old ERP print window. */
  @media print { body { padding: 0; } }
  ${printRules(onePerPage)}
</style>
</head>
<body>${body}</body>
</html>`;
}

/** Print the framed report with the legacy stylesheet's own @media print rules. */
export function printLegacyReportFrame(frame: HTMLIFrameElement | null) {
  const win = frame?.contentWindow;
  if (!win) return;
  win.focus();
  win.print();
}

type Props = {
  html: string;
  frameRef?: React.RefObject<HTMLIFrameElement | null>;
  title?: string;
  className?: string;
  /** One report card per printed page (default). Set false for grand-marksheet templates. */
  onePerPage?: boolean;
};

export default function LegacyReportFrame({ html, frameRef, title = 'Generated report cards', className, onePerPage = true }: Props) {
  const innerRef = useRef<HTMLIFrameElement>(null);
  const ref = (frameRef ?? innerRef) as React.RefObject<HTMLIFrameElement>;
  const srcDoc = useMemo(() => buildLegacyReportDocument(html, API_BASE_URL, onePerPage), [html, onePerPage]);

  // Grow the frame to its content so the page scrolls, not a nested box.
  useEffect(() => {
    const frame = ref.current;
    if (!frame) return;
    let observer: ResizeObserver | undefined;
    const fit = () => {
      const doc = frame.contentDocument;
      if (doc) frame.style.height = `${doc.documentElement.scrollHeight}px`;
    };
    const onLoad = () => {
      fit();
      const doc = frame.contentDocument;
      if (doc && typeof ResizeObserver !== 'undefined') {
        observer?.disconnect();
        observer = new ResizeObserver(fit); // logos / stylesheet finishing later change the height
        observer.observe(doc.documentElement);
      }
    };
    frame.addEventListener('load', onLoad);
    return () => {
      frame.removeEventListener('load', onLoad);
      observer?.disconnect();
    };
  }, [ref, srcDoc]);

  return (
    <iframe
      ref={ref}
      title={title}
      srcDoc={srcDoc}
      // No allow-scripts: markup can't run code. allow-same-origin lets us size/print it, allow-modals lets print() run.
      sandbox="allow-same-origin allow-modals"
      className={className ?? 'block w-full rounded-lg border border-slate-200 bg-white'}
      style={{ minHeight: 320 }}
    />
  );
}
